import base64
import zlib
import pygame

FOES = {'eye': (53, 46, '', ''), 'harpy': (54, 81, '', ''), 'garg': (79, 84, '', '')}
FCACHE = {}


def foe_frame(kind, fr):
  """Frame (0-5) of 'eye', 'harpy' or 'garg': pixel-art flyers facing left."""
  key = (kind, fr % 6)
  s = FCACHE.get(key)
  if s is None:
    w, h, pal, data = FOES[kind]
    if (kind, "raw") not in FCACHE:
      FCACHE[(kind, "pal")] = [None] + [tuple(int(pal[i + k:i + k + 2], 16) for k in (0, 2, 4)) for i in range(0, len(pal), 6)]
      FCACHE[(kind, "raw")] = zlib.decompress(base64.b64decode(data))
    raw, p = FCACHE[(kind, "raw")], FCACHE[(kind, "pal")]
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = key[1] * w * h
    for i in range(w * h):
      v = raw[base + i]
      if v:
        s.set_at((i % w, i // w), p[v] + (255,))
    FCACHE[key] = s
  return s
